// Exactly one corrective regeneration, with the violations fed back into the prompt.
// Unbounded retry loops against a subjective scorer are how a system burns a budget overnight.
const attempt = $('Envelope In').first().json.payload._brand_attempt || 0;
if (attempt >= 1) {
  return [{ json: { give_up: true, status: 'warn', reason: 'brand_floor_not_met_after_one_correction', escalate_to_human: true } }];
}
const v = ($json.violations || []).map(x => `${x.rule}: ${x.fix}`).join('; ');
return [{ json: { _brand_attempt: attempt + 1, prompt_suffix: `\n\nBrand corrections required: ${v}` } }];

const items = $input.all().map(i => i.json);
return [{ json: {
  assets: items.filter(a => a.asset_id),
  usable: items.filter(a => a.asset_id && a.status !== 'fail').length,
  escalations: items.filter(a => a.escalate_to_human),
  reused: items.filter(a => a.deduped || a.reused).length
} }];
